grid.getRowHeader = (row, depth) => ({ value: memberAt(layout.rows[depth], row, depth) });
grid.getColHeader = (depth, col) => ({ value: memberAt(layout.columns[depth], col, depth) });

// and the size of the thing you are claiming to have:
